import base64
import hashlib
import os
import secrets
import time
from dataclasses import dataclass
from typing import Dict, Optional
from urllib.parse import urlencode, urlparse, parse_qs

import requests


@dataclass
class PKCELoginConfig:
    domain: str
    client_id: str
    redirect_uri: str
    audience: Optional[str] = None
    scope: str = "openid profile email offline_access"
    authorization_endpoint: Optional[str] = None
    token_endpoint: Optional[str] = None


class PKCELoginFlow:
    def __init__(self, config: PKCELoginConfig):
        self.config = config
        self._state = None
        self._code_verifier = None

    @staticmethod
    def _base64url_no_padding(data: bytes) -> str:
        return base64.urlsafe_b64encode(data).decode("ascii").rstrip("=")

    @staticmethod
    def _sha256(verifier: str) -> str:
        digest = hashlib.sha256(verifier.encode("ascii")).digest()
        return PKCELoginFlow._base64url_no_padding(digest)

    def _auth_endpoint(self) -> str:
        if self.config.authorization_endpoint:
            return self.config.authorization_endpoint
        return f"https://{self.config.domain}/authorize"

    def _token_endpoint(self) -> str:
        if self.config.token_endpoint:
            return self.config.token_endpoint
        return f"https://{self.config.domain}/oauth/token"

    def create_authorization_url(self) -> Dict[str, str]:
        self._state = secrets.token_urlsafe(32)
        self._code_verifier = self._base64url_no_padding(os.urandom(64))
        code_challenge = self._sha256(self._code_verifier)

        params = {
            "response_type": "code",
            "client_id": self.config.client_id,
            "redirect_uri": self.config.redirect_uri,
            "scope": self.config.scope,
            "state": self._state,
            "code_challenge": code_challenge,
            "code_challenge_method": "S256",
        }
        if self.config.audience:
            params["audience"] = self.config.audience

        return {
            "authorization_url": f"{self._auth_endpoint()}?{urlencode(params)}",
            "state": self._state,
            "code_verifier": self._code_verifier,
        }

    def validate_callback(self, callback_url: str) -> str:
        parsed = urlparse(callback_url)
        query = parse_qs(parsed.query)
        returned_state = query.get("state", [None])[0]
        code = query.get("code", [None])[0]
        error = query.get("error", [None])[0]

        if error:
            error_desc = query.get("error_description", [""])[0]
            raise RuntimeError(f"Authorization error: {error}: {error_desc}")

        if not code:
            raise ValueError("Authorization code not found in callback URL")

        if not returned_state or returned_state != self._state:
            raise ValueError("Invalid or missing state parameter")

        return code

    def exchange_code_for_tokens(self, code: str) -> Dict:
        if not self._code_verifier:
            raise RuntimeError("PKCE code verifier is missing; call create_authorization_url first")

        data = {
            "grant_type": "authorization_code",
            "client_id": self.config.client_id,
            "code": code,
            "redirect_uri": self.config.redirect_uri,
            "code_verifier": self._code_verifier,
        }

        response = requests.post(self._token_endpoint(), data=data, timeout=30)
        response.raise_for_status()
        token_response = response.json()

        expires_in = token_response.get("expires_in")
        if expires_in is not None:
            token_response["expires_at"] = int(time.time()) + int(expires_in)

        return token_response

    def login(self, callback_url: str) -> Dict:
        code = self.validate_callback(callback_url)
        return self.exchange_code_for_tokens(code)
